<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;
use CetechDeliveryEngine\Domain\CustomerPolicy\{PolicyFamilyRecord as R,PolicyJson};
use CetechDeliveryEngine\Domain\PolicyAssignment\{PolicyAssignmentMap,PolicyAssignmentState,PolicyEffectiveSelection};
use CetechDeliveryEngine\Domain\RuleLifecycle\RuleTime;
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\CustomerPolicyDomainFixture as F;
use CetechDeliveryEngine\Tests\Support\PolicyAssignment\PolicyAssignmentDomainFixture as P;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
final class DomainPolicyFamilyRecordTest extends TestCase {
    #[DataProvider('families')]
    public function test_genuine_c01_ecr_capture_preserves_all_private_authored_fields_and_four_customer_fields(string$family):void{$r=F::capture($family)['record'];self::assertSame($family,$r->family());$f=$r->facts();self::assertSame('PRIVATE supplied policy',$f['content']->name);self::assertSame("Literal <em>text</em>.\r\n\tEnd.",$f['content']->full_text);self::assertSame(['disposition','customer_title','summary','full_text','exceptions'],array_keys($r->customer_fields()));self::assertSame('assigned',$r->customer_fields()['disposition']);self::assertStringNotContainsString('PRIVATE',json_encode($r->customer_fields(),JSON_THROW_ON_ERROR));self::assertSame(12,count(get_object_vars($f['source']->reference)));self::assertSame($r->private_json(),R::from_private_json($r->private_json())->private_json());self::assertNotSame($r->digest(),$r->material_digest());}
    public static function families():array{return[['return_policy_v1'],['refund_policy_v1']];}
    #[DataProvider('dispositions')]
    public function test_disabled_and_not_assigned_are_distinct_and_have_no_fabricated_wording(string$family,string$mode):void{$r=F::capture($family,$mode)['record'];self::assertSame($mode,$r->disposition());self::assertNull($r->facts()['content']);self::assertSame(['disposition'=>$mode,'customer_title'=>null,'summary'=>null,'full_text'=>null,'exceptions'=>null],$r->customer_fields());self::assertSame($r->digest(),R::from_private_json($r->private_json())->digest());}
    public static function dispositions():array{$out=[];foreach(self::families()as[$family])foreach(['disabled','not_assigned']as$mode){$out[]=[$family,$mode];}return$out;}
    public function test_capture_time_does_not_change_material_but_source_or_authored_bytes_do():void{$a=F::capture()['record'];$b=F::capture(at:'2026-10-24 12:00:01.000000')['record'];$c=F::capture(content:['name'=>'Another private name'])['record'];self::assertSame($a->material_digest(),$b->material_digest());self::assertNotSame($a->digest(),$b->digest());self::assertNotSame($a->material_digest(),$c->material_digest());self::assertSame($a->customer_fields(),$c->customer_fields());}
    public function test_variation_keeps_exact_complete_parent_chain():void{$r=F::capture(variation:true)['record'];$f=$r->facts();self::assertCount(3,$f['source']->chain);self::assertSame(44,$f['source']->coordinate->scope_id);self::assertSame(33,$f['source']->coordinate->parent_id);$wrong=$f;$wrong['source']->coordinate->parent_id=34;$this->refused(static fn()=>R::from_private_json(PolicyJson::encode($wrong)));}
    public function test_current_pointers_without_complete_history_are_not_a_frozen_original_source():void{$f=F::capture();$s=$f['snapshot'];$partial=new \CetechDeliveryEngine\Domain\RuleLifecycle\RuleSnapshot($s->profile,$s->guard,$s->logicals,$s->versions,true,false);$selection=PolicyEffectiveSelection::assigned('return_policy_v1',$partial,P::uuid(101),$f['at'],$f['resolved']['provenance']['return_policy_v1'],$f['resolved']['fingerprint']);$this->refused(static fn()=>R::capture($selection,$f['coordinate'],4,$f['states'],$partial));}
    public function test_unresolved_capture_is_never_frozen_as_no_policy():void{$f=F::capture(mode:'unresolved');$this->refused(static fn()=>R::capture($f['selection'],$f['coordinate'],4,$f['states'],null));}
    public function test_wrong_offer_site_parent_and_incomplete_chain_never_capture():void{$f=F::capture();foreach([static fn()=>R::capture($f['selection'],$f['coordinate'],0,$f['states'],$f['snapshot']),static fn()=>R::capture($f['selection'],$f['coordinate'],5,$f['states'],$f['snapshot']),static fn()=>R::capture($f['selection'],array_replace($f['coordinate'],['site_id'=>2]),4,$f['states'],$f['snapshot']),static fn()=>R::capture($f['selection'],$f['coordinate'],4,[$f['states'][1]],$f['snapshot']),static fn()=>R::capture($f['selection'],$f['coordinate'],4,array_reverse($f['states']),$f['snapshot'])]as$make){$this->refused($make);}}
    public function test_valid_but_unrelated_typed_selection_is_not_equal_to_captured_chain():void{$f=F::capture();$forged=PolicyEffectiveSelection::assigned('return_policy_v1',$f['snapshot'],P::uuid(101),$f['at'],[],str_repeat('a',64));$this->refused(static fn()=>R::capture($forged,$f['coordinate'],4,$f['states'],$f['snapshot']));}
    public function test_more_specific_disable_cannot_be_ignored_by_an_ancestor_selection():void{$f=F::capture();$states=$f['states'];$states[1]=P::state(returns:PolicyAssignmentMap::empty(1,'return_policy_v1')->with_instruction(0,['mode'=>'disabled']));$this->refused(static fn()=>R::capture($f['selection'],$f['coordinate'],4,$states,$f['snapshot']));}
    #[DataProvider('mutations')]
    public function test_saved_codec_rejects_modified_immutable_c01_or_chain_fact(string$path,mixed$value):void{$f=F::capture()['record']->facts();$parts=explode('.',$path);$root=&$f;$last=array_pop($parts);foreach($parts as$p){if(is_array($root)){$root=&$root[$p];}else{$root=&$root->{$p};}}if(is_array($root)){$root[$last]=$value;}else{$root->{$last}=$value;}$this->refused(static fn()=>R::from_private_json(PolicyJson::encode($f)));}
    public static function mutations():array{return[
        ['format',2],['definition_hash',str_repeat('a',64)],['disposition','unresolved'],['family','promise'],['content.name','changed'],['content.customer_title','changed'],['content.full_text','changed'],['content.exceptions','new'],['source.real_offer_id',0],['source.evaluated_at',P::CREATED],['source.assignment_fingerprint',str_repeat('f',64)],['source.selection_fingerprint',str_repeat('f',64)],['source.candidate_digest',str_repeat('f',64)],['source.guard.revision',999],['source.logical.current_published_version_id',12],['source.logical.scope_hash',str_repeat('f',64)],['source.logical.revision',999],['source.version.state','draft'],['source.version.content_hash',str_repeat('f',64)],['source.version.priority',1],['source.version.payload_json','{}'],['source.version.effective_until',P::NOW],['source.reference.version_id',12],['source.reference.hypothetical',true],['source.provenance.row_id',51],['source.chain.0.row_id',0],['source.chain.0.bytes','{}'],['source.reference',null],['source.version',null],['source.provenance',null]];}
    public function test_unknown_fields_duplicate_keys_and_noncanonical_json_refuse():void{$r=F::capture()['record'];$f=$r->facts();$f['unknown']='PRIVATE';$this->refused(static fn()=>R::from_private_json(PolicyJson::encode($f)));$this->refused(static fn()=>R::from_private_json(' '.$r->private_json()));$this->refused(static fn()=>R::from_private_json('{"format":1,"format":1}'));}
    public function test_detached_facts_and_debug_do_not_mutate_or_disclose_private_source():void{$r=F::capture()['record'];$f=$r->facts();$f['content']->name='modified';self::assertSame('PRIVATE supplied policy',$r->facts()['content']->name);ob_start();var_dump($r);$debug=ob_get_clean();self::assertStringNotContainsString('PRIVATE',$debug);foreach([static fn()=>json_encode($r,JSON_THROW_ON_ERROR),static fn()=>serialize($r)]as$make){try{$make();self::fail('Implicit private projection allowed');}catch(\LogicException){self::assertTrue(true);}}}
    private function refused(callable$make):void{$rejected=false;try{$make();}catch(\InvalidArgumentException){$rejected=true;}self::assertTrue($rejected,'Invalid family record was accepted.');}
}
